sys_script_include.script:
var SVPDPUtils = Class.create();
SVPDPUtils.prototype = {
	initialize: function () {
	},

	menuItemCondition: function (menuItemID) {
		var gr = new GlideRecord('sp_rectangle_menu_item');
		gr.get(menuItemID);

		if (gr.sp_rectangle_menu.toString() == 'f20072fc97f30f14d3efb73de053afb7') {
			if (gr.type == 'page') {
				switch (gr.sp_page.id.toString()) {
					case 'kb_home':
						return true;
					case 'my_requests':
						return $sp.canSeePage('my_requests') && gs.isLoggedIn();
					default:
						return false;
				}
			}

			if (gr.type == 'sc') {
				return GlideSPScriptable.canSeePage("sc_home") && gs.isLoggedIn();
			}
		}
	},

	type: 'SVPDPUtils'
};
